"use client";

import { useEffect, useState } from "react";
import { createClient } from "@/lib/supabase/client";
import Link from "next/link";


export default function Dashboard() {

  const supabase = createClient();

  const [business, setBusiness] = useState<any>(null);
  const [services, setServices] = useState<any[]>([]);
  const [appointments, setAppointments] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);



  useEffect(() => {

    loadDashboard();

  }, []);





  async function loadDashboard() {

    setLoading(true);


    const {
      data:{user}
    } = await supabase.auth.getUser();



    if(!user){

      setLoading(false);
      return;

    }





    const {data:groomer,error:groomerError} = await supabase
      .from("groomers")
      .select("*")
      .eq("user_id",user.id)
      .maybeSingle();




    if(groomerError || !groomer){

      console.log(groomerError);
      setLoading(false);
      return;

    }



    setBusiness(groomer);






    const {data:serviceData}=await supabase
      .from("services")
      .select("*")
      .eq("groomer_id",groomer.id);



    setServices(serviceData || []);








    // ONLY LOAD PENDING APPOINTMENTS

    const {data:appointmentData,error:appointmentError}=await supabase
      .from("appointments")
      .select("*")
      .eq("groomer_id",groomer.id)
      .eq("status","pending")
      .order("created_at",{ascending:false});




    if(appointmentError){

      console.log(appointmentError);

    }



    setAppointments(appointmentData || []);


    setLoading(false);

  }









  async function updateAppointment(
    id:string,
    status:string
  ){


    const appointment = appointments.find(
      (item)=>item.id === id
    );



    if(!appointment){

      return;

    }







    // SAVE STATUS TO DATABASE

    const {data,error}=await supabase
      .from("appointments")
      .update({

        status:status

      })
      .eq("id",id)
      .select();






    if(error){

      alert(error.message);
      console.log(error);
      return;

    }





    console.log("UPDATED:",data);






    let customerMessage = "";



    if(status==="completed"){

      customerMessage =
      "🐾 Your request has been accepted! Let's discuss the details here.";

    }



    if(status==="cancelled"){

      customerMessage =
      "Sorry, this seller declined your request.";

    }







    if(customerMessage){


      const {error:messageError}=await supabase
        .from("messages")
        .insert({

          groomer_id:business.id,

          customer_id:appointment.customer_id,

          sender_type:"groomer",

          message:customerMessage

        });



      if(messageError){

        console.log(messageError);

      }


    }







    // REMOVE FROM DASHBOARD

    setAppointments((old)=>
      old.filter(
        (item)=>item.id !== id
      )
    );


  }








  if(loading){

    return (

      <main className="min-h-screen bg-green-50 flex items-center justify-center">

        <h1 className="text-3xl font-bold text-green-700">
          🐾 Loading PawStop...
        </h1>

      </main>

    );

  }








  return (

    <main className="min-h-screen bg-green-50 p-6">


      <div className="max-w-5xl mx-auto">



        <h1 className="text-4xl font-bold text-green-700">
          🐾 PawStop Dashboard
        </h1>







        {business && (

          <div className="bg-white rounded-3xl shadow p-6 mt-6">


            <h2 className="text-2xl font-bold">

              {business.business_name}

            </h2>


            <p className="text-gray-500">

              {business.address}

            </p>


          </div>

        )}









        <div className="flex flex-wrap justify-between items-center mt-10 gap-3">


          <h2 className="text-2xl font-bold">
            ✂️ Services
          </h2>




          <div className="flex gap-3">


            <Link
              href="/services"
              className="bg-green-600 text-white px-5 py-2 rounded-xl"
            >

              Add Service

            </Link>




            <Link
              href="/dashboard/messages"
              className="bg-gray-800 text-white px-5 py-2 rounded-xl"
            >

              💬 Messages

            </Link>


          </div>


        </div>








        <div className="grid md:grid-cols-3 gap-5 mt-5">


          {services.map((service)=>(


            <div
              key={service.id}
              className="bg-white rounded-2xl shadow p-5"
            >

              <h3 className="font-bold text-xl">

                {service.name}

              </h3>


              <p>

                ${service.price_cents / 100}

              </p>


              <p className="text-gray-500">

                {service.duration_minutes} minutes

              </p>


            </div>


          ))}


        </div>







        <h2 className="text-2xl font-bold mt-10">
          📅 New Appointments
        </h2>







        <div className="space-y-5 mt-5">



        {appointments.map((app)=>(


          <div
            key={app.id}
            className="bg-white rounded-2xl shadow p-5"
          >



            <h3 className="text-xl font-bold">

              🐶 {app.dog_name}

            </h3>



            <p>
              Customer: {app.client_name}
            </p>



            <p>
              Phone: {app.client_phone}
            </p>



            <p>
              Address: {app.client_address}
            </p>






            <div className="flex flex-wrap gap-3 mt-4">



              <button
                onClick={()=>updateAppointment(app.id,"completed")}
                className="bg-green-600 text-white px-4 py-2 rounded-xl"
              >
                ✅ Accept
              </button>





              <button
                onClick={()=>updateAppointment(app.id,"cancelled")}
                className="bg-red-600 text-white px-4 py-2 rounded-xl"
              >
                ❌ Decline
              </button>





              <button
                onClick={()=>updateAppointment(app.id,"no-show")}
                className="bg-gray-700 text-white px-4 py-2 rounded-xl"
              >
                🚫 No Show
              </button>



            </div>



          </div>


        ))}







        {appointments.length===0 && (

          <div className="bg-white rounded-2xl p-6">

            No new appointments.

          </div>

        )}



        </div>


      </div>


    </main>

  );

}